public class SaveRole {
    public void save(@PathVariable("sheetId") String sheetId, @Val RoleValues values, RoleRepository roles,
            Out<Role> role) {
        role.set(roles.save(new Role(sheetId.trim(), values.user(), values.role())));
    }
}
